#     use the "angle" value from JSON whenever available.
#
# False:
#     ignore JSON angle and use the fallback orientation.
USE_JSON_ANGLE = True

# JSON angle convention:
#
#   0°   = Revit +X
#   90°  = Revit +Y
#   180° = Revit -X
#   270° = Revit -Y
#
# If your detector outputs the angle in the opposite direction,
# change ANGLE_SIGN to -1.
ANGLE_SIGN = 1.0

# If the detector's angle is relative to the CAD/DXF X-axis rather
# than Revit's X-axis, this offset can be adjusted.
#
# Normally leave this at 0.
ANGLE_OFFSET_DEG = 0.0

# Fallback when JSON has no usable angle.
VERTICAL_FALLBACK_DEG = 0.0
HORIZONTAL_FALLBACK_DEG = 90.0

# ---------------------------------------------------------------------------
# POSITION SETTINGS
# ---------------------------------------------------------------------------

