# ===========================================================================
# SAFE REVIT HELPERS
# ===========================================================================

def safe_element_name(element):

    if element is None:
        return ""

    try:
        value = element.Name
        if value:
            return str(value)
    except Exception:
        pass

    try:
        p = element.get_Parameter(
            BuiltInParameter.SYMBOL_NAME_PARAM
        )

        if p is not None:
            value = p.AsString()

            if value:
                return value

    except Exception:
        pass

    return ""


def safe_family_name(symbol):

    if symbol is None:
        return ""

    try:
        value = symbol.FamilyName

        if value:
            return str(value)

    except Exception:
        pass

    try:
        family = symbol.Family

        if family is not None:

            try:
                value = family.Name

                if value:
                    return str(value)

            except Exception:
                pass

    except Exception:
        pass

    return ""


def safe_symbol_name(symbol):

    if symbol is None:
        return ""

    try:
        value = symbol.Name

        if value:
            return str(value)

    except Exception:
        pass

    try:
        p = symbol.get_Parameter(
            BuiltInParameter.SYMBOL_NAME_PARAM
        )

        if p is not None:

            value = p.AsString()

            if value:
                return value

    except Exception:
        pass

    return ""


def safe_element_id_value(element_id):

    if element_id is None:
        return None

    try:
        return int(element_id.Value)
    except Exception:
        pass

    try:
        return int(element_id.IntegerValue)
    except Exception:
        pass

    try:
        return int(str(element_id))
    except Exception:
        return None


def get_instance_family_name(instance):

    if instance is None:
        return ""

    try:
        return safe_family_name(instance.Symbol)
    except Exception:
        return ""


# ===========================================================================
# ORIENTATION HELPERS
# ===========================================================================

def normalize_angle(angle):

    """
    Normalize angle into 0 <= angle < 360.
    """

    try:
        angle = float(angle)
    except Exception:
        return None

    angle = angle % 360.0

    if angle < 0:
        angle += 360.0

    return angle


def get_json_angle(g):

    """
    Read the actual angle from JSON.

    Supported keys:

        angle
        rotation
        rotation_angle
        angle_deg
        orientation_angle

    Returns None if no valid angle exists.
    """

    # Original File2 read "rotation" first. DXF text rotation is
    # almost always 0, so every family landed at 0°. Use the
    # detector's family rotation only.
    possible_keys = [
        "revit_angle",
        "angle",
        "orientation_angle",
    ]

    for key in possible_keys:

        value = g.get(key, None)

        if value is None:
            continue

        try:

            angle = float(value)
            if key == "orientation_angle":
                folded = angle % 180.0
                if folded < 0:
                    folded += 180.0
                if abs(folded - 180.0) < 1e-6:
                    folded = 0.0
                angle = (folded + 90.0) % 180.0
                if abs(angle - 180.0) < 1e-6:
                    angle = 0.0

            return normalize_angle(
                angle * ANGLE_SIGN
                + ANGLE_OFFSET_DEG
            )

        except Exception:
            pass

    return None


def get_orientation(g):

    """
    Determine the orientation and actual rotation angle.

    Priority:

        1. JSON angle
        2. orientation string
        3. vertical fallback
    """

    orientation = str(
        g.get(
            "orientation",
            ""
        )
    ).upper().strip()

    json_angle = None

    if USE_JSON_ANGLE:
        json_angle = get_json_angle(g)

    if json_angle is not None:

        return (
            orientation if orientation else "ANGLE",
            json_angle,
            "JSON angle"
        )

    if orientation == "HORIZONTAL":

        return (
            "HORIZONTAL",
            normalize_angle(
                HORIZONTAL_FALLBACK_DEG
            ),
            "fallback"
        )

    if orientation == "VERTICAL":

        return (
            "VERTICAL",
            normalize_angle(
                VERTICAL_FALLBACK_DEG
            ),
            "fallback"
        )

    return (
        orientation if orientation else "UNKNOWN",
        normalize_angle(
            VERTICAL_FALLBACK_DEG
        ),
        "fallback"
    )


# ===========================================================================
# READ JSON
# ===========================================================================

if not os.path.isfile(JSON_PATH):

    OUT = (
        "JSON NOT FOUND:\n\n{}"
    ).format(
        JSON_PATH
    )

    raise FileNotFoundError(OUT)


with open(
    JSON_PATH,
    "r"
) as f:

    data = json.load(f)


gondolas = data.get(
    "gondolas",
    []
)


# ===========================================================================
# CONNECT TO REVIT
# ===========================================================================

doc = DocumentManager.Instance.CurrentDBDocument

if doc is None:

    raise Exception(
        "Could not obtain current Revit document."
    )


# ===========================================================================
# FIND CAD IMPORT
# ===========================================================================

cad_offset_x = 0.0
cad_offset_y = 0.0

cad_rotation_rad = 0.0

cad_offset_info = (
    "No CAD transform found. "
    "Using origin (0,0)."
)

all_cad_found = []


all_imports = list(
    FilteredElementCollector(doc)
    .OfClass(ImportInstance)
)


selected_import = None


for imp in all_imports:

    try:

        sym = doc.GetElement(
            imp.GetTypeId()
        )

        cad_name_str = ""

        try:

            p = sym.get_Parameter(
                BuiltInParameter.IMPORT_SYMBOL_NAME
            )

            if p is not None:

                cad_name_str = (
                    p.AsString()
                    or ""
                )

        except Exception:
            pass


        if not cad_name_str:

            cad_name_str = safe_element_name(sym)


        if not cad_name_str:

            continue


        transform = imp.GetTotalTransform()

        origin = transform.Origin

        ox = origin.X
        oy = origin.Y


        # ---------------------------------------------------------------
        # Extract X-axis direction from CAD transform
        # ---------------------------------------------------------------

        bx = transform.BasisX

        cad_angle = math.atan2(
            bx.Y,
            bx.X
        )


        try:

            link_type = (
                "Link"
                if imp.IsLinked
                else "Import"
            )

        except Exception:

            link_type = "Import"


        all_cad_found.append(
            "    [{}] {} | "
            "offset=({:.0f},{:.0f}) mm | "
            "rotation={:.3f}°".format(
                link_type,
                cad_name_str,
                ox * 304.8,
                oy * 304.8,
                math.degrees(cad_angle)
            )
        )


        # ---------------------------------------------------------------
        # Select CAD
        # ---------------------------------------------------------------

        if CAD_LINK_NAME:

            if (
                CAD_LINK_NAME.lower()
                not in cad_name_str.lower()
            ):

                continue

        lowered = cad_name_str.lower()
        is_proposed_cad = (
            "propos" in lowered
            or "selling floor" in lowered
        )
        is_existing_cad = (
            "existing" in lowered
            and "condition" in lowered
        )
        if is_proposed_cad and not is_existing_cad:
            continue

        info_text = (
            "[{}] {} | "
            "offset=({:.3f},{:.3f}) ft "
            "= ({:.0f},{:.0f}) mm | "
            "rotation={:.3f}°"
        ).format(
            link_type,
            cad_name_str,
            ox,
            oy,
            ox * 304.8,
            oy * 304.8,
            math.degrees(cad_angle)
        )

        if selected_import is None:

            selected_import = imp

            cad_offset_x = ox
            cad_offset_y = oy

            cad_rotation_rad = cad_angle

            cad_offset_info = info_text

        if is_existing_cad:

            selected_import = imp

            cad_offset_x = ox
            cad_offset_y = oy

            cad_rotation_rad = cad_angle

            cad_offset_info = info_text

    except Exception as ex:

        all_cad_found.append(
            "    CAD ERROR: {}".format(
                str(ex)
            )
        )


# ===========================================================================
# FAMILY SYMBOL LOOKUP
# ===========================================================================

all_symbols = list(
    FilteredElementCollector(doc)
    .OfClass(FamilySymbol)
)


symbol_lookup = {}

symbol_errors = []


for s in all_symbols:

    try:

        family_name = safe_family_name(s)

        type_name = safe_symbol_name(s)

        if family_name and type_name:

            symbol_lookup[
                (family_name, type_name)
            ] = s

    except Exception as ex:

        symbol_errors.append(
            str(ex)
        )


# ===========================================================================
# FIND MISSING TYPES
# ===========================================================================

missing = []


for code, mapping in TYPE_MAP.items():

    fname, tname = mapping

    if (
        fname,
        tname
    ) not in symbol_lookup:

        missing.append(
            "  {} → {} / {}".format(
                code,
                fname,
                tname
            )
        )


# ===========================================================================
# FIND LEVEL
# ===========================================================================

all_levels = list(
    FilteredElementCollector(doc)
    .OfClass(Level)
)


level_map = {}


for lv in all_levels:

    try:

        if lv.Name:

            level_map[
                str(lv.Name)
            ] = lv

    except Exception:
        pass


target_level = level_map.get(
    LEVEL_NAME
)


if target_level is None:

    for name, lv in level_map.items():

        if (
            name.strip().lower()
            ==
            LEVEL_NAME.strip().lower()
        ):

            target_level = lv

            break


if target_level is None:

    raise Exception(
        "Level '{}' not found.\n\n"
        "Available levels:\n{}".format(
            LEVEL_NAME,
            "\n".join(
                "  " + n
                for n in sorted(
                    level_map.keys()
                )
            )
        )
    )


# ===========================================================================
# FIND EXISTING CONDITIONS VIEW
# Never Proposed / overlay. Prefer 1.0 EXISTING CONDITIONS - GROUND.
# ===========================================================================

all_views = list(
    FilteredElementCollector(doc)
    .OfClass(ViewPlan)
)


def _view_scope(name):
    text = str(name or "").lower()
    if "propos" in text or "selling floor" in text:
        return "proposed"
    if "overlay" in text:
        return "overlay"
    if "existing" in text and "condition" in text:
        return "existing"
    return "other"


target_view = None
preferred_view = VIEW_NAME.strip().lower()

for v in all_views:
    try:
        name = str(v.Name)
        if preferred_view and name.strip().lower() == preferred_view:
            if _view_scope(name) != "existing":
                continue
            target_view = v
            break
    except Exception:
        pass

if target_view is None:
    for v in all_views:
        try:
            name = str(v.Name)
            if _view_scope(name) != "existing":
                continue
            if "ground" in name.lower() or "1.0" in name or "1-0" in name:
                target_view = v
                break
        except Exception:
            pass

if target_view is None:
    for v in all_views:
        try:
            if _view_scope(v.Name) == "existing":
                target_view = v
                break
        except Exception:
            pass


# ===========================================================================
# USE VIEW LEVEL IF DIFFERENT
# ===========================================================================

level_override_info = ""


if target_view is not None:

    try:

        view_level = target_view.GenLevel

        if (
            view_level is not None
            and view_level.Id
            != target_level.Id
        ):

            level_override_info = (
                "View '{}' uses level '{}'."
            ).format(
                target_view.Name,
                view_level.Name
            )

            target_level = view_level

    except Exception:
        pass


# ===========================================================================
# BLUE GRAPHICS
# ===========================================================================

BLUE = Color(
    0,
    102,
    204
)


color_override = OverrideGraphicSettings()


try:

    color_override.SetProjectionLineColor(
        BLUE
    )

except Exception:
    pass


try:

    color_override.SetSurfaceForegroundPatternColor(
        BLUE
    )

    color_override.SetSurfaceForegroundPatternVisible(
        True
    )

except Exception:
    pass


# ===========================================================================
# EXISTING PHASE
# ===========================================================================

all_phases = list(
    FilteredElementCollector(doc)
    .OfClass(Phase)
)


existing_phase = None


for ph in all_phases:

    try:

        name = str(
            ph.Name
        ).lower()

        if name in (
            "existing",
            "existing construction",
            "as-built"
        ):

            existing_phase = ph

            break

    except Exception:
        pass


if (
    existing_phase is None
    and all_phases
):

    existing_phase = all_phases[0]


phase_info = (
    existing_phase.Name
    if existing_phase
    else "not set"
)


# ===========================================================================
# TRANSACTION
# ===========================================================================

t = Transaction(
    doc,
    "Place Existing Conditions Gondolas"
)

t.Start()


# ===========================================================================
# DELETE PREVIOUSLY MANAGED GONDOLAS
# ===========================================================================

MANAGED_FAMILIES = {
    "Floor_Gondola",
    "Floor_Gondola_High_Bay",
    "Floor_Gondola_High_Bay-Half_Bay",
    "Wall_Gondola",
    "Wall_Gondola_High_Bay",
    "End_Panel_Decks",
    "Decks_&_Hopper",
    "End_Panel",
    "Floor_Gondola_Queuing"
}


deleted_count = 0


all_instances = list(
    FilteredElementCollector(doc)
    .OfClass(FamilyInstance)
    .ToElements()
)


for inst in all_instances:

    try:

        family_name = (
            get_instance_family_name(inst)
        )

        if (
            family_name
            not in MANAGED_FAMILIES
        ):

            continue


        # ---------------------------------------------------------------
        # LEVEL CHECK
        # ---------------------------------------------------------------

        lv_param = None

        try:

            lv_param = inst.get_Parameter(
                BuiltInParameter.FAMILY_LEVEL_PARAM
            )

        except Exception:
            pass


        if lv_param is None:

            try:

                lv_param = inst.get_Parameter(
                    BuiltInParameter.INSTANCE_REFERENCE_LEVEL_PARAM
                )

            except Exception:
                pass


        if lv_param is not None:

            try:

                if (
                    lv_param.AsElementId()
                    != target_level.Id
                ):

                    continue

            except Exception:
                continue


        # ---------------------------------------------------------------
        # PHASE CHECK
        # ---------------------------------------------------------------

        if existing_phase is not None:

            try:

                ph_param = inst.get_Parameter(
                    BuiltInParameter.PHASE_CREATED
                )

                if ph_param is not None:

                    if (
                        ph_param.AsElementId()
                        != existing_phase.Id
                    ):

                        continue

            except Exception:
                pass


        doc.Delete(
            inst.Id
        )

        deleted_count += 1


    except Exception:
        pass


doc.Regenerate()


# ===========================================================================
# ACTIVATE SYMBOLS
# ===========================================================================

activated = set()


for code, mapping in TYPE_MAP.items():

    fname, tname = mapping

    key = (
        fname,
        tname
    )

    if key not in symbol_lookup:
        continue

    try:

        symbol = symbol_lookup[key]

        if (
            not symbol.IsActive
            and key not in activated
        ):

            symbol.Activate()

            activated.add(key)

    except Exception:
        pass


doc.Regenerate()


# ===========================================================================
# PLACE GONDOLAS
# ===========================================================================

placed = []
skipped = []
wall_placed = []
orientation_report = []


for g in gondolas:

    try:

        # ---------------------------------------------------------------
        # CODE
        # ---------------------------------------------------------------

        code = str(
            g.get(
                "code",
                ""
            )
        ).upper().strip()


        if code not in TYPE_MAP:

            skipped.append(
                "UNKNOWN CODE: {}".format(
                    code
                )
            )

            continue


        # ---------------------------------------------------------------
        # FAMILY / TYPE
        # ---------------------------------------------------------------

        fname, tname = TYPE_MAP[code]

        key = (
            fname,
            tname
        )


        if key not in symbol_lookup:

            skipped.append(
                "MISSING TYPE: {} → {} / {}".format(
                    code,
                    fname,
                    tname
                )
            )

            continue


        symbol = symbol_lookup[key]


        # ---------------------------------------------------------------
        # JSON COORDINATES
        # ---------------------------------------------------------------

        x_mm = float(
            g.get(
                "x",
                0
            )
        )

        y_mm = float(
            g.get(
                "y",
                0
            )
        )


        # ---------------------------------------------------------------
        # CONVERT TO FEET
        # ---------------------------------------------------------------

        x_local_ft = (
            x_mm * MM_TO_FT
        )

        y_local_ft = (
            y_mm * MM_TO_FT
        )


        # ---------------------------------------------------------------
        # APPLY CAD TRANSFORM
        # ---------------------------------------------------------------

        if APPLY_CAD_ROTATION:

            cos_a = math.cos(
                cad_rotation_rad
            )

            sin_a = math.sin(
                cad_rotation_rad
            )

            x_rot = (
                x_local_ft * cos_a
                -
                y_local_ft * sin_a
            )

            y_rot = (
                x_local_ft * sin_a
                +
                y_local_ft * cos_a
            )

        else:

            x_rot = x_local_ft
            y_rot = y_local_ft


        if APPLY_CAD_TRANSLATION:

            x_ft = (
                x_rot
                + cad_offset_x
            )

            y_ft = (
                y_rot
                + cad_offset_y
            )

        else:

            x_ft = x_rot
            y_ft = y_rot


        z_ft = target_level.Elevation


        point = XYZ(
            x_ft,
            y_ft,
            z_ft
        )


        # ---------------------------------------------------------------
        # PLACE FAMILY
        # ---------------------------------------------------------------

        instance = doc.Create.NewFamilyInstance(
            point,
            symbol,
            target_level,
            StructuralType.NonStructural
        )


        # ---------------------------------------------------------------
        # PHASE
        # ---------------------------------------------------------------

        if existing_phase is not None:

            try:

                p_created = instance.get_Parameter(
                    BuiltInParameter.PHASE_CREATED
                )

                if (
                    p_created is not None
                    and not p_created.IsReadOnly
                ):

                    p_created.Set(
                        existing_phase.Id
                    )

            except Exception:
                pass


        # ---------------------------------------------------------------
        # BLUE OVERRIDE
        # ---------------------------------------------------------------

        if target_view is not None:

            try:

                target_view.SetElementOverrides(
                    instance.Id,
                    color_override
                )

            except Exception:
                pass


        # ---------------------------------------------------------------
        # DETERMINE ACTUAL ORIENTATION
        # ---------------------------------------------------------------

        orientation, angle_deg, angle_source = (
            get_orientation(g)
        )


        # ---------------------------------------------------------------
        # ROTATE ABOUT INSTANCE INSERTION POINT
        # ---------------------------------------------------------------

        if (
            angle_deg is not None
            and abs(angle_deg) > 0.0001
        ):

            angle_rad = math.radians(
                angle_deg
            )

            axis = Line.CreateBound(
                point,
                XYZ(
                    point.X,
                    point.Y,
                    point.Z + 1.0
                )
            )

            ElementTransformUtils.RotateElement(
                doc,
                instance.Id,
                axis,
                angle_rad
            )


        # ---------------------------------------------------------------
        # REPORT
        # ---------------------------------------------------------------

        placed.append(
            "{:<24} "
            "@ ({:>9.0f}, {:>9.0f}) mm "
            "angle={:>8.3f}° "
            "{}".format(
                code,
                x_mm,
                y_mm,
                angle_deg
                if angle_deg is not None
                else 0.0,
                angle_source
            )
        )


        orientation_report.append(
            "{} | orientation={} | angle={:.3f}° | source={}".format(
                code,
                orientation,
                angle_deg
                if angle_deg is not None
                else 0.0,
                angle_source
            )
        )


        # ---------------------------------------------------------------
        # WALL GONDOLAS
        # ---------------------------------------------------------------

        if (
            fname
            in (
                "Wall_Gondola",
                "Wall_Gondola_High_Bay"
            )
        ):

            eid_int = safe_element_id_value(
                instance.Id
            )

            wall_placed.append(
                "{:<24} "
                "@ ({:>9.0f}, {:>9.0f}) mm "
                "angle={:>8.3f}° "
                "id={}".format(
                    code,
                    x_mm,
                    y_mm,
                    angle_deg
                    if angle_deg is not None
                    else 0.0,
                    eid_int
                )
            )


    except Exception as ex:

        skipped.append(
            "ERROR {} :: {}".format(
                g.get(
                    "code",
                    "?"
                ),
                str(ex)
            )
        )


# ===========================================================================
# COMMIT
# ===========================================================================

t.Commit()


# ===========================================================================
# REPORT
# ===========================================================================

sep = "=" * 75


lines = [

    "",
    sep,
    " EXISTING CONDITIONS — GONDOLA PLACEMENT",
    sep,
    "",

    "Script version         : {}".format(
        SCRIPT_VERSION
    ),

    "JSON path              : {}".format(
        JSON_PATH
    ),

    "Total JSON items       : {}".format(
        len(gondolas)
    ),

    "Placed                 : {}".format(
        len(placed)
    ),

    "Skipped                : {}".format(
        len(skipped)
    ),

    "Deleted previous       : {}".format(
        deleted_count
    ),

    "",

    "LEVEL",
    "  Level used           : {}".format(
        target_level.Name
    ),

    "  Elevation            : {:.3f} ft".format(
        target_level.Elevation
    ),

    "  Level note           : {}".format(
        level_override_info
        if level_override_info
        else "Matched LEVEL_NAME"
    ),

    "",

    "PHASE",
    "  Phase used           : {}".format(
        phase_info
    ),

    "",

    "CAD TRANSFORM",
    "  {}".format(
        cad_offset_info
    ),

    "",

    "ORIENTATION",
    "  JSON angle enabled   : {}".format(
        USE_JSON_ANGLE
    ),

    "  Angle sign           : {}".format(
        ANGLE_SIGN
    ),

    "  Angle offset         : {:.3f}°".format(
        ANGLE_OFFSET_DEG
    ),

    "  CAD rotation applied : {}".format(
        APPLY_CAD_ROTATION
    ),

    "",

    "ALL CAD IMPORTS:"
]


if all_cad_found:

    lines.extend(
        all_cad_found
    )

else:

    lines.append(
        "    NONE FOUND"
    )


# ===========================================================================
# ORIENTATION REPORT
# ===========================================================================

lines.extend(
    [
        "",
        "ORIENTATION USED FOR EACH ITEM:"
    ]
)


if orientation_report:

    lines.extend(
        [
            "    " + x
            for x in orientation_report
        ]
    )

else:

    lines.append(
        "    NONE"
    )


# ===========================================================================
# WALL GONDOLAS
# ===========================================================================

if wall_placed:

    lines.extend(
        [
            "",
            "WALL GONDOLAS PLACED: {}".format(
                len(wall_placed)
            )
        ]
    )

    lines.extend(
        [
            "    " + x
            for x in wall_placed
        ]
    )


# ===========================================================================
# MISSING TYPES
# ===========================================================================

if missing:

    lines.extend(
        [
            "",
            "MISSING REVIT TYPES:"
        ]
    )

    lines.extend(
        [
            "    " + x
            for x in missing
        ]
    )


# ===========================================================================
# SYMBOL ERRORS
# ===========================================================================

if symbol_errors:

    lines.extend(
        [
            "",
            "SYMBOL LOOKUP WARNINGS:"
        ]
    )

    lines.extend(
        [
            "    " + x
            for x in symbol_errors
        ]
    )


# ===========================================================================
# SKIPPED
# ===========================================================================

if skipped:

    lines.extend(
        [
            "",
            "SKIPPED / ERRORS:"
        ]
    )

    lines.extend(
        [
            "    " + x
            for x in skipped
        ]
    )


# ===========================================================================
# PLACED
# ===========================================================================

lines.extend(
    [
        "",
        "PLACED GONDOLAS:"
    ]
)


lines.extend(
    [
        "    " + x
        for x in placed
    ]
)


lines.extend(
    [
        "",
        sep,
        ""
    ]
)


# ===========================================================================
# DYNAMO OUTPUT
# ===========================================================================

OUT = "\n".join(
    lines
)